using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using SkyIsland;using System.Reflection;
public static class BackpackReview {
 static int Total(BackpackState b,string kind)=>BackpackRules.Count(b,kind)+b.overflow.Where(s=>s.item==kind).Sum(s=>s.count);
 static BackpackState Full(){var b=BackpackRules.Empty();for(int i=0;i<35;i++)b.slots[i]=new ItemStack("stone",64);return b;}
 public static void Validate(){int n=0;Action<bool,string> check=(ok,msg)=>{if(!ok)throw new Exception("BACKPACK FAIL "+msg);n++;};var b=BackpackRules.Empty();check(BackpackRules.Valid(b)&&b.slots.Count==35,"27 main plus8 hotbar");check(BackpackRules.Add(b,"wood",130)&&b.slots[27].count==64&&b.slots[28].count==64&&b.slots[29].count==2,"materials split into64 stacks");check(BackpackRules.Add(b,"axe",2)&&b.slots[30].count==1&&b.slots[31].count==1,"tools each occupy one slot");int wood=BackpackRules.Count(b,"wood");check(BackpackRules.Click(b,27,true)&&b.cursor.count==32&&b.slots[27].count==32,"right click takes half");check(BackpackRules.Click(b,0,true)&&b.slots[0].count==1&&b.cursor.count==31,"right click places one");check(BackpackRules.Click(b,0,false)&&b.slots[0].count==32&&b.cursor.count==0,"left merges remaining hand");check(BackpackRules.Count(b,"wood")==wood,"splitting conserves items");check(BackpackRules.QuickMove(b,0)&&b.slots[0].count==0&&BackpackRules.Count(b,"wood")==wood,"shift moves main to hotbar");check(BackpackRules.QuickMove(b,27)&&b.slots[0].count>0,"shift moves hotbar to main");check(BackpackRules.Click(b,30,false)&&b.cursor.item=="axe","pick tool");check(BackpackRules.Click(b,0,false)&&b.slots[0].item=="axe"&&b.cursor.item=="wood","swap incompatible stacks");check(BackpackRules.ReturnCursor(b)&&b.cursor.count==0&&BackpackRules.Count(b,"wood")==130,"closing returns cursor without loss");
  var bad=BackpackRules.Copy(b);bad.slots[0].count=2;check(!BackpackRules.Valid(bad),"tool stack over1 rejected");bad=BackpackRules.Copy(b);bad.slots[0].item="unknown";check(!BackpackRules.Valid(bad),"unknown item rejected");bad=BackpackRules.Copy(b);bad.slots.RemoveAt(0);check(!BackpackRules.Valid(bad),"wrong grid shape rejected");b=Full();var before=JsonUtility.ToJson(b);check(!BackpackRules.Add(b,"wood",1)&&JsonUtility.ToJson(b)==before,"full add no mutation");b.cursor=new ItemStack("wood",1);check(!BackpackRules.ReturnCursor(b)&&b.cursor.count==1,"full cursor remains recoverable");check(!BackpackRules.Click(b,0,true)&&b.cursor.item=="wood","right click cannot swap different kinds");
  var island=new HexIsland{Wood=1000000,Stone=500};var state=new SurvivalState{axes=2,pickaxes=1,benches=1,panels=80,food=20};BackpackBridge.Migrate(island,state);check(Total(state.bag,"wood")==1000000&&Total(state.bag,"stone")==500&&Total(state.bag,"panel")==80&&Total(state.bag,"axe")==2,"old stock fully preserved including overflow");check(state.bag.overflow.Count>0&&BackpackRules.Valid(state.bag),"migration overflow explicit valid");var restored=JsonUtility.FromJson<SurvivalState>(JsonUtility.ToJson(state));check(BackpackRules.Valid(restored.bag)&&Total(restored.bag,"wood")==1000000,"overflow save reload");int current=island.Wood;BackpackBridge.Migrate(island,state);check(Total(state.bag,"wood")==1000000&&island.Wood==current,"migration idempotent no duplicate");
  island=new HexIsland{Wood=100};state=new SurvivalState();BackpackBridge.Migrate(island,state);var inv=new SurvivalInventory(island,state);check(inv.Collect("stone",500)&&BackpackBridge.Sync(island,state)&&BackpackRules.Count(state.bag,"stone")==500,"collection reaches real stacks");island.Wood-=3;check(BackpackBridge.Sync(island,state)&&BackpackRules.Count(state.bag,"wood")==97,"construction debit removes stacks");check(!inv.Collect("unknown",1),"unknown pickup rejected");state.bag=Full();BackpackBridge.Apply(island,state);check(!inv.CanCollect("wood",1),"full bag capacity checked before pickup");state.bag.slots[0]=new ItemStack("wood",6);BackpackBridge.Apply(island,state);check(inv.Craft("bench",new Hex(0,0),out _)&&BackpackBridge.Sync(island,state)&&BackpackRules.Count(state.bag,"bench")==1,"craft consumes then fits output in freed slot");check(!inv.Craft("bench",new Hex(0,0),out _),"insufficient materials no extra craft");
  state.bag=Full();state.bag.slots[0]=new ItemStack();BackpackBridge.Apply(island,state);check(inv.CanCollect("wood",64)&&inv.CanCollect("food",64)&&!inv.CanCollectMany(new Dictionary<string,int>{{"wood",64},{"food",64}}),"combined loot checks shared capacity atomically");
  state.bag=BackpackRules.Empty();state.bag.slots[27]=new ItemStack("axe",1);state.selectedSlot=0;BackpackBridge.Apply(island,state);check(PanelDismantle.AxeEquipped(state)&&inv.HarvestAmount("wood")==3,"axe works in moved hotbar slot");state.bag.slots[27]=new ItemStack("pickaxe",1);BackpackBridge.Apply(island,state);check(inv.HarvestAmount("stone")==2&&!PanelDismantle.AxeEquipped(state),"pick works without fixed slot assumption");state.bag.slots[27]=new ItemStack();state.bag.slots[1]=new ItemStack("axe",1);BackpackBridge.Apply(island,state);check(!PanelDismantle.AxeEquipped(state),"stored axe not equipped");
  state.bag.cursor=new ItemStack("food",7);BackpackBridge.Apply(island,state);restored=JsonUtility.FromJson<SurvivalState>(JsonUtility.ToJson(state));check(restored.bag.cursor.count==7&&restored.food==7,"cursor persists across interruption");check(BackpackRules.ReturnCursor(restored.bag)&&BackpackRules.Count(restored.bag,"food")==7,"recovered cursor returns once");var dropped=new GroundItemState{item="axe",count=1,position=Vector3.one};state.groundItems.Add(dropped);restored=JsonUtility.FromJson<SurvivalState>(JsonUtility.ToJson(state));check(restored.groundItems.Count==1&&restored.groundItems[0].Valid(),"ground drop persists");dropped.count=2;check(!dropped.Valid(),"invalid tool ground stack rejected");
  // Model a capacity-paused tree using the actual collection and save bridge.
  island=new HexIsland();state=new SurvivalState();BackpackBridge.Migrate(island,state);inv=new SurvivalInventory(island,state);var nature=new NatureWorldState{initialized=true};var tree=new NatureSpawn{kind=0,health=3,cell=new Hex(-1,0)};NatureRules.Add(nature,tree);for(int i=0;i<30;i++)NatureRules.Harvest(nature,tree,inv,island,1,()=>BackpackBridge.Sync(island,state));check(island.Wood==300&&BackpackRules.Count(state.bag,"wood")==300&&nature.nodes.Count==0,"30 second tree feeds64 stacks exactly300");state.bag=Full();BackpackBridge.Apply(island,state);tree=new NatureSpawn{kind=0,health=3,cell=new Hex(-1,0)};nature.nodes.Clear();NatureRules.Add(nature,tree);check(NatureRules.Harvest(nature,tree,inv,island,1,()=>true)=="full"&&tree.harvestedSeconds==0,"full bag pauses harvest without losing resource");
  island=new HexIsland{Wood=20};state=new SurvivalState();BackpackBridge.Migrate(island,state);string original=JsonUtility.ToJson(state.bag);check(!BackpackBridge.Edit(island,state,bag=>BackpackRules.Click(bag,31,false),()=>false)&&JsonUtility.ToJson(state.bag)==original&&island.Wood==20,"UI pickup rollback on save failure");check(!BackpackBridge.Edit(island,state,bag=>BackpackRules.Click(bag,31,false),()=>throw new IOException())&&state.bag.cursor.count==0,"UI exception rollback");check(BackpackBridge.Edit(island,state,bag=>BackpackRules.Click(bag,31,true),()=>true)&&state.bag.cursor.count==10&&island.Wood==20,"UI split keeps total aliases");check(BackpackBridge.Edit(island,state,bag=>BackpackRules.ReturnCursor(bag),()=>true)&&BackpackRules.Count(state.bag,"wood")==20,"close returns cursor exactly once");
  var data=new GroundItemState{item="wood",count=1,position=Vector3.one};state.groundItems.Add(data);bool droppedOk=BackpackBridge.Edit(island,state,bag=>BackpackRules.Take(bag,"wood",1),()=>true);check(droppedOk&&island.Wood==19&&state.groundItems[0].count==1,"drop moves one item to saved ground record");var savedState=JsonUtility.FromJson<SurvivalState>(JsonUtility.ToJson(state));check(BackpackRules.Count(savedState.bag,"wood")+savedState.groundItems.Sum(d=>d.count)==20,"drop and inventory conserved in snapshot");
  PanelDismantleReview.Validate();NatureResourceReview.Validate();AdventureReview.Validate();HarborReview.Validate();MovementReview.Validate();AuthorityReview.Validate();Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/backpack-tests.txt","PASS "+n+" backpack/stack/cursor/split/shift/migration/overflow/crafting/pickup/selection/save assertions; UTC "+DateTime.UtcNow.ToString("o")+"\nLocal rules and main-project compile. Real UI mouse/touch and gameplay release pending.");Debug.Log("SKY_BACKPACK_TESTS_PASS "+n);
 }
 public static void ValidateScene(){Validate();PrototypeBuild.Prepare();var p=UnityEngine.Object.FindObjectOfType<SkyIslandPrototype>();p.SendMessage("Awake");const BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;var state=(SurvivalState)typeof(SkyIslandPrototype).GetField("survival",f).GetValue(p);var island=(HexIsland)typeof(SkyIslandPrototype).GetField("island",f).GetValue(p);var inventory=(SurvivalInventory)typeof(SkyIslandPrototype).GetField("inventory",f).GetValue(p);if(!BackpackRules.Valid(state.bag))throw new Exception("Scene bag not initialized");if(!inventory.Collect("wood",300)||!inventory.Collect("axe",1)||!BackpackBridge.Sync(island,state))throw new Exception("Scene pickup failed");int slot=state.bag.slots.FindIndex(s=>s.item=="axe")-27;if(slot<0)throw new Exception("Scene tool not in hotbar");typeof(SkyIslandPrototype).GetMethod("SelectSlot",f).Invoke(p,new object[]{slot});if(!PanelDismantle.AxeEquipped(state)||typeof(SkyIslandPrototype).GetField("heldTool",f).GetValue(p)==null)throw new Exception("Scene equipped tool missing");var save=island.Snapshot(Vector3.zero);save.survival=state;var restored=JsonUtility.FromJson<IslandSave>(JsonUtility.ToJson(save));if(!BackpackRules.Valid(restored.survival.bag)||BackpackRules.Count(restored.survival.bag,"wood")!=300)throw new Exception("Scene save mismatch");Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/backpack-scene-tests.txt","PASS initialized35 slots / real main-scene collection / dynamic hotbar tool model / snapshot roundtrip; UTC "+DateTime.UtcNow.ToString("o")+"\nEditor-assembled main scene; mouse UI and touch interaction not validated. No playable build released.");Debug.Log("SKY_BACKPACK_SCENE_PASS 4");}

}
